RARY));\\r\\n        navPlaylists.setOnClickListener(v -> showTab(TAB_PLAYLISTS));\\r\\n        findViewById(R.id.newPlaylistButton).setOnClickListener(v -> createPlaylist());\\r\\n        findViewById(R.id.emptyNewPlaylist).setOnClickListener(v -> createPlaylist());\\r\\n\"\nRep 'wire-tabs' $old $new\n$old = \"        navHome.setOnClickListener(v -> showTab(false));\\r\\n\"\n$new = \"        navHome.setOnClickListener(v -> showTab(TAB_HOME));\\r\\n\"\nRep 'wire-home' $old $new\nRep 'share-tab' 'showTab(false);' 'showTab(TAB_HOME);'\n$old = \"        songsList.setAdapter(songAdapter);\\r\\n    }\\r\\n\"\n$new = \"        songsList.setAdapter(songAdapter);\\r\\n\\r\\n        playlistAdapter = new PlaylistAdapter(new PlaylistAdapter.Actions() {\\r\\n            @Override\\r\\n            public void onOpen(Playlist playlist) {\\r\\n                openPlaylist(playlist);\\r\\n            }\\r\\n\\r\\n            @Override\\r\\n            public void onMore(View anchor, Playlist playlist) {\\r\\n                showPlaylistMenu(playlist);\\r\\n            }\\r\\n        });\\r\\n        playlistsList.setLayoutManager(new LinearLayoutManager(this));\\r\\n        playlistsList.setAdapter(playlistAdapter);\\r\\n    }\\r\\n\"\nRep 'setup-lists' $old $new\n$old = \"                new MenuSheet.Item(R.drawable.ic_delete, \\\"Delete from device\\\", true,\\r\\n                        () -> confirmDelete(track)));\\r\\n\"\n$new = \"                new MenuSheet.Item(R.drawable.ic_add, \\\"Add to playlist\\\",\\r\\n                        () -> addToPlaylist(track)),\\r\\n                new MenuSheet.Item(R.drawable.ic_delete, \\\"Delete from device\\\", true,\\r\\n                        () -> confirmDelete(track)));\\r\\n\"\nRep 'song-menu' $old $new\n$old = \"        if (requestCode != REQ_DELETE) return;\\r\\n\"\n$new = \"        if (PlaylistActions.onActivityResult(this, requestCode, resultCode, data,\\r\\n                this::refreshPlaylists)) return;\\r\\n        if